async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  if (!sessionStore?.listFor) return sendSessionList(ws, []);

  try {
    const summaries = await sessionStore.listFor(session.userId, listOptions(message));
    sendSessionList(ws, summaries.map(toSummaryFrame));
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    log.error('ws', 'failed to list sessions', {userId: session.userId, error: reason});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

function listOptions(message: ListSessionsMessage): SessionListOptions | undefined {
  const options: SessionListOptions = {
    ...(message.limit !== undefined ? {limit: message.limit} : {}),
    ...(message.before !== undefined ? {before: message.before} : {}),
  };
  return Object.keys(options).length > 0 ? options : undefined;
}

function toSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}

